const fs = require("fs");
const path = require("path");

const OPENAPI_PATH = path.resolve(__dirname, "../openapi.json");
const MODELS_PATH = path.resolve(__dirname, "../src/models.ts");
const API_TYPES_PATH = path.resolve(__dirname, "../../../backend/src/types/api.types.ts");

const JSONB_OVERRIDES = {
  Clip: ["clip_metadata", "input_metadata"],
};

const spec = JSON.parse(fs.readFileSync(OPENAPI_PATH, "utf-8"));
const schemaNames = Object.keys(spec.components?.schemas || {});

function generateModels() {
  const lines = [
    '// Auto-generated by scripts/generate-models.js — do not edit manually',
    'import type { components } from "./generated/api";',
    "",
  ];

  for (const name of schemaNames) {
    const overrides = JSONB_OVERRIDES[name];
    if (overrides) {
      const omitFields = overrides.map((f) => `"${f}"`).join(" | ");
      const anyFields = overrides.map((f) => `  ${f}?: any;`).join("\n");
      lines.push(
        `export type ${name} = Omit<components["schemas"]["${name}"], ${omitFields}> & {`,
        anyFields,
        `};`
      );
    } else {
      lines.push(`export type ${name} = components["schemas"]["${name}"];`);
    }
  }

  lines.push("");
  fs.writeFileSync(MODELS_PATH, lines.join("\n"));
  console.log(`Generated ${schemaNames.length} type aliases in models.ts`);
}

function generateApiTypes() {
  const lines = [
    '// Auto-generated by packages/shared-types/scripts/generate-models.js — do not edit manually',
    `import type {`,
    ...schemaNames.map((n) => `  ${n} as Shared${n},`),
    `} from "@clipper/shared-types";`,
    "",
    "type DbCompatible<T> = {",
    "  [K in keyof T]?: any;",
    "} & Record<string, any>;",
    "",
  ];

  for (const name of schemaNames) {
    if (name === "ErrorResponse") {
      lines.push(`export type ${name} = Shared${name};`);
    } else {
      lines.push(`export type ${name} = DbCompatible<Shared${name}>;`);
    }
  }

  lines.push("");
  fs.writeFileSync(API_TYPES_PATH, lines.join("\n"));
  console.log(`Generated ${schemaNames.length} bridge types in api.types.ts`);
}

generateModels();
generateApiTypes();
